public class BiomeBuilder extends BuilderBase<Biome> {
	public transient Biome.ClimateSettings climate;
	public transient Biome.BiomeEffects effects;
	public transient Biome.BiomeGenerationSettings generationSettings;
	public transient Biome.SpawnSettings spawnSettings;

	public BiomeBuilder(ResourceLocation id) {
		super(id);
		this.climate = Biome.ClimateSettings.plain();
		this.effects = new Biome.BiomeEffects.Builder().build();
		this.generationSettings = new Biome.BiomeGenerationSettings.Builder().build();
		this.spawnSettings = new Biome.SpawnSettings.Builder().build();
	}

	@Info("Sets the biome's precipitation type.")
	public BiomeBuilder precipitation(Biome.Precipitation v) {
		climate = new Biome.ClimateSettings.Builder().precipitation(v).build();
		return this;
	}

	@Info("Sets the biome's temperature.")
	public BiomeBuilder temperature(float v) {
		climate = new Biome.ClimateSettings.Builder().temperature(v).build();
		return this;
	}

	@Info("Sets the biome's downfall.")
	public BiomeBuilder downfall(float v) {
		climate = new Biome.ClimateSettings.Builder().downfall(v).build();
		return this;
	}
